public V get(K key) {
    V val = cache.get(key);
    if (val == null) {
        synchronized (locks.computeIfAbsent(key, k -> new Object())) {
            val = cache.get(key);
            if (val == null) {
                val = database.fetch(key);
                cache.put(key, val);
            }
        }
    }
    return val;
}
